# Shared bilingual descriptions for every non-pipe registered item, including BlockItems.
function Item-DescriptionTranslations {
    $details=[ordered]@{
        uranium_ore=@('含铀的普通石质矿石。','使用铁镐或更高级的镐采集，通常掉落1粗铀；时运增加产量，精准采集保留矿石。矿物生成待后续配置。','Uranium ore in ordinary stone.','Requires an iron pickaxe or better. Drops one raw uranium, increased by Fortune; Silk Touch preserves the ore. World generation is not yet configured.')
        deepslate_uranium_ore=@('含铀的深板岩矿石。','使用铁镐或更高级的镐采集，通常掉落1粗铀；时运和精准采集同普通矿石，硬度更高。矿物生成待后续配置。','Uranium ore in deepslate.','Requires an iron pickaxe or better. Drops one raw uranium with Fortune/Silk Touch support; harder than ordinary ore. World generation is not yet configured.')
        raw_uranium=@('从铀矿石中开采出的粗铀。','普通铀矿石和深层铀矿石均可掉落，支持时运；后续精炼与加工配方待配置。','Raw uranium mined from uranium ore.','Drops from both ordinary and deepslate uranium ore, with Fortune support. Refining and processing recipes are not yet configured.')
        uranium_ingot=@('绿色金属外观的铀锭。','核能材料，已注册forge:ingots/uranium标签；加工配方待后续配置。','A uranium ingot with a green metallic appearance.','Nuclear material tagged forge:ingots/uranium. Processing recipes are not yet configured.')
        uranium_dust=@('绿色的铀粉末材料。','核能加工原料，已注册forge:dusts/uranium标签；加工配方待后续配置。','Green uranium powder.','Nuclear processing material tagged forge:dusts/uranium. Processing recipes are not yet configured.')
        machine_casing=@('构成多方块机器的外壳。','外表面必须完整；内部除核心外可放空气或合法机器部件。','Forms the shell of a multiblock machine.','Complete the entire surface; other interior spaces may contain air or valid machine parts.')
        reinforced_casing=@('构成防爆外壳，保护成型机器。','自身防爆；成型结构含有强化外壳时，整台机器获得爆炸保护。','Explosion-resistant machine casing.','Resists explosions itself and protects a formed machine containing it.')
        structural_glass=@('可透光的机器外壳，可观察机器内部。','相邻结构玻璃连接边框；可以用于完整外表面或内部。','Light-transmitting casing for viewing machine interiors.','Adjacent glass joins its frames; valid on the shell or inside the machine.')
        energy_coil=@('降低机器配方的基础耗能。','每个减少20%%基础耗能，最多%s个生效；单份最低1 FE/t。','Reduces base recipe energy cost.','Each subtracts 20%% of base energy, up to %s effective; minimum 1 FE/t per recipe.')
        efficiency_coil=@('提高机器加工速度，同时增加耗能。','每个速度+15%%、耗能倍率+10%%，加法叠加，无额外数量上限。','Speeds up processing at an increased energy cost.','Each adds 15%% speed and 10%% energy multiplier, additively, without a count cap.')
        energy_matrix=@('增加机器电池容量，也可组成独立储能矩阵。','每个增加%s FE；独立储能矩阵只用外壳与能量矩阵，工程锤成型后右键切换充放电模式。','Expands machine batteries or forms a standalone storage matrix.','Each adds %s FE; build a casing-and-cell battery, form it with the hammer and right-click for charge/discharge modes.')
        processing_matrix=@('增加每轮可并行处理的配方份数。','每个并行上限+1、耗能倍率+15%%，无额外数量上限；资源与耗能按实际份数增加。','Increases the number of recipes processed in each cycle.','Each adds one parallel recipe and 15%% energy multiplier, without a count cap; resource use and energy scale with the batch.')
        machine_controller=@('打开和管理整台多方块机器。','外表面恰好放1个；工程锤选区各轴3–%s格，内部中心放对应核心。','Opens and controls the formed multiblock machine.','Place exactly one on the surface; each selected axis is 3–%s blocks, with the core at the center.')
        item_vault=@('储存物品，竖向堆叠扩展机器库存。','每段%s槽；机器内通过顶部或底部相邻的通用端口输入输出。','Stores items; vertical stacking expands machine inventory.','Each segment adds %s slots; machine automation uses universal ports directly above or below the column.')
        fluid_tank=@('兼容旧存档的储罐，默认识别为流体。','每段%s mB，可在清空后存流体或气体；同列不能混装，机器内通过通用端口传输。','Legacy-compatible tank, initially identified as fluid.','Each segment adds %s mB; empty tanks accept fluid or gas without mixing. Use universal ports inside machines.')
        gas_tank=@('兼容旧存档的储罐，默认识别为气体。','每段%s mB，可在清空后存流体或气体；同列不能混装，气体需要本模组兼容接口。','Legacy-compatible tank, initially identified as gas.','Each segment adds %s mB; empty tanks accept fluid or gas without mixing. Gases require the compatible gas API.')
        storage_tank=@('通用储罐，可储存流体或本模组气体。','每段%s mB，竖向合列；按实际内容识别介质，同列一次只能存一种介质，清空后可换。','Universal tank for fluids or this mod''s gases.','Each segment adds %s mB and joins vertically. Contents determine the phase; empty the column before switching resource types.')
        universal_port=@('随相邻仓储自动识别物品或流体/气体接口。','紧贴仓储列上端或下端；扳手右键切换输入1/2、输出1/2，同列端口必须同一通道。','Automatically adapts its resource interface to the attached storage.','Attach directly above/below a column. Wrench-click cycles Input 1/2 and Output 1/2; every port on one column shares a channel.')
        item_port=@('兼容旧存档的端口，现与通用端口功能相同。','按相邻仓储自动识别介质；连接列的上/下端，扳手切换输入输出通道。','Legacy-compatible port with the same behavior as a universal port.','Adapts to the attached store. Connect above/below its column and wrench-click to change input/output channels.')
        fluid_port=@('兼容旧存档的端口，现与通用端口功能相同。','按相邻仓储自动识别介质；连接列的上/下端，扳手切换输入输出通道。','Legacy-compatible port with the same behavior as a universal port.','Adapts to the attached store. Connect above/below its column and wrench-click to change input/output channels.')
        gas_port=@('兼容旧存档的端口，现与通用端口功能相同。','按相邻仓储自动识别介质；连接列的上/下端，扳手切换输入输出通道。','Legacy-compatible port with the same behavior as a universal port.','Adapts to the attached store. Connect above/below its column and wrench-click to change input/output channels.')
        crusher_core=@('放在选区内部中心，将结构识别为粉碎机。','至少两个独立物品仓列，输入1、输出1各27槽；默认1粗铁/铜/金产出2对应粉末。','Identifies a machine as a crusher when placed at its center.','Needs separate Input 1 and Output 1 vaults, at least 27 slots each. Default raw iron/copper/gold recipes yield two dusts.')
        industrial_core=@('工业类机器共用的中心核心。','正上方紧贴机型组件构建工业机器；或同高东、西、南、北紧贴燃料棒构建核反应堆。各机型使用独立配方与仓储条件。','Shared central core for industrial machines.','Select industrial machines with a component above, or a nuclear reactor with fuel rods directly north, south, east and west. Each has independent recipes and storage.')
        boiler_core=@('锅炉类机器的中心核心。','与锅炉结构配件组合生成蒸汽；蒸汽可供涡轮发电机使用。','Central core for boiler machines.','Combine with boiler structure parts to generate steam for turbine generators.')
        forging_component=@('与工业核心组合，选择锻压机。','必须紧贴工业核心正上方；使用锻压机独立配方，没有默认加工配方。','Selects a forging press with an industrial core.','Place directly above the industrial core. Uses independent forging recipes; none ship by default.')
        forming_component=@('与工业核心组合，选择物品塑形机。','紧贴工业核心正上方；输入1物品仓、输出1物品仓各一列，执行独立塑形配方，目前无默认案例。','Selects an item forming machine with an industrial core.','Place directly above the industrial core. Separate item Input 1/Output 1 columns; independent forming recipes, none provided by default.')
        infusion_component=@('与工业核心组合，选择灌注机。','紧贴工业核心正上方；输入1物品、输入2流体或气体、输出1物品，恰好三列独立仓储。','Selects an infuser with an industrial core.','Place directly above the industrial core. Exactly three independent columns: item Input 1, fluid OR gas Input 2, item Output 1.')
        calcination_component=@('与熔炼核心组合，选择电弧炉。','必须紧贴熔炼核心正上方；兼容当前熔炼配方，使用FE替代燃料。','Selects an arc furnace with a smelting core.','Place directly above the smelting core. Uses loaded furnace recipes with FE instead of fuel.')
        alloy_component=@('与熔炼核心组合，选择合金冶炼机。','必须紧贴熔炼核心正上方；三列仓储分别为主料输入1、辅料输入2、物品输出1。','Selects an alloy smelter with a smelting core.','Place directly above the smelting core. Use main Input 1, additive Input 2 and item Output 1 columns.')
        compound_component=@('与反应核心组合，选择双相反应釜。','必须紧贴反应核心正上方；输入1、输入2、输出1各一列独立仓储。','Selects a biphasic reactor with a reaction core.','Place directly above the reaction core; separate Input 1, Input 2 and Output 1 columns are required.')
        decomposition_component=@('与反应核心组合，选择单入双出分离机。','必须紧贴反应核心正上方；输入1、输出1、输出2各一列，支持物品/流体/气体分解及混合介质输出。','Selects a one-input, two-output separator with a reaction core.','Place directly above the reaction core. Use Input 1, Output 1 and Output 2; supports item, fluid, gas and mixed-output decomposition.')
        smelting_core=@('熔炼类机器的中心核心。','正上方放煅烧组件构成电弧炉，放合金组件构成合金冶炼机；组件必须紧贴核心。','Central core for smelting machines.','Place a calcination component directly above for an arc furnace, or an alloy component for an alloy smelter.')
        reaction_core=@('反应与分离机器共用的中心核心。','正上方紧贴化合组件构成反应釜，紧贴分解组件构成分离机；介质组合选择具体机型。','Shared central core for reactions and separation.','Place a combination component directly above for a reactor, or a decomposition component for a separator; stores select the profile.')
        conversion_core=@('搭配流体罐和气体罐，构成气液转化机。','恰好一列流体罐和一列气体罐；GUI切换液化/气化，转化内容由配方定义。','Forms a gas/liquid converter with fluid and gas tanks.','Exactly one fluid and one gas tank column; choose liquefaction or vaporization in the GUI. Recipes define conversions.')
        alloy_core=@('旧版合金核心，仅保留存档兼容。','构建请改用熔炼核心，并在其正上方紧贴合金组件。','Legacy alloy core retained for saved worlds.','Build with a smelting core and an alloy component directly above it.')
        separation_core=@('旧版分离核心，仅保留存档兼容。','构建请改用反应核心，并在其正上方紧贴分解组件。','Legacy separation core retained for saved worlds.','Build with a reaction core and a decomposition component directly above it.')
        power_core=@('储存电力，为连通电网提供FE。','当前容量%s FE；一个网络只允许一个核心，接入外部FE电源后供电。','Stores FE for a connected power grid.','Current capacity: %s FE. Only one core per grid; feed it from an external FE source.')
        signal_pole=@('转接电网连接，延伸电网线路。','占1×1×5，拆任意段移除整杆；当前连线距离上限%s格，本身不为机器供电。','Relays grid connections over distance.','Occupies 1×1×5; breaking any segment removes it. Current link range: %s blocks. Does not power machines directly.')
        power_pylon=@('向覆盖范围内的机器供电。','连线最远%s格；以底座为中心覆盖水平%s×%s、上下各%s格，按机器核心位置判定。','Supplies power to machines within its coverage.','Link range %s; coverage %s×%s horizontally and %s blocks above/below its base, checked at each machine core.')
        creative_power_source=@('提供可供提取的无限FE，方便创造模式测试。','需要兼容设备提取电力，不会自行向电网推送；不提供生存合成配方。','Supplies extractable unlimited FE for creative testing.','A compatible device must extract its power; it does not actively push FE. No survival crafting recipe.')
        wrench=@('配置机器端口通道和管道端面模式。','右键端口切换通道；Shift+右键管道支臂切换模式，普通右键查看当前模式。','Configures machine channels and pipe faces.','Wrench-click ports to cycle channels. Shift-click a pipe arm to change its mode; normal click inspects it.')
        engineering_hammer=@('框选长方体并检测、构建多方块机器。','依次右键两个相对角点；Shift+右键方块或空气取消，失败时按原因修复后重选第二点。','Selects a cuboid and validates or forms a multiblock machine.','Click opposite corners; Shift-right-click a block or air to cancel. Fix reported errors and select the second corner again.')
        tutorial_book=@('右键打开教程，查看构建、供电、运输和机器说明。','可右键空气或方块；主手空置时支持副手打开，阅读不消耗物品。','Right-click to read building, power, transport and machine guidance.','Use in the air or on blocks; also works in the offhand with an empty main hand. Reading never consumes the book.')
        turbine_core=@('构成横向涡轮发电机的核心。','至少一个涡轮转子、一个蒸汽输入罐和一个能量矩阵；转子必须与矩阵共用X或Z轴。','Core for a horizontal turbine generator.','Requires a turbine rotor, a steam input tank and an energy matrix; rotors must share an X or Z axis with the matrix.')
        turbine_rotor=@('涡轮发电机的风扇转子，成型后自动对齐水平轴线。','每个转子默认提供%s FE/t并消耗%s mB蒸汽/t；运行转速随整机实际耗汽增加，缺汽或满电时停转。','Fan rotor that automatically aligns with the formed turbine shaft.','Each rotor provides %s FE/t and consumes %s mB steam/t; rotation speeds up with actual turbine steam use and stops when starved or full.')
        iron_dust=@('铁的粉末材料。','默认由粉碎机处理粗铁获得：每1个粗铁产出2个铁粉；后续用途以已加载配方为准。','Powdered iron material.','Default crusher recipe: one raw iron yields two iron dusts. Further uses depend on loaded recipes.')
        copper_dust=@('铜的粉末材料。','默认由粉碎机处理粗铜获得：每1个粗铜产出2个铜粉；后续用途以已加载配方为准。','Powdered copper material.','Default crusher recipe: one raw copper yields two copper dusts. Further uses depend on loaded recipes.')
        gold_dust=@('金的粉末材料。','默认由粉碎机处理粗金获得：每1个粗金产出2个金粉；后续用途以已加载配方为准。','Powdered gold material.','Default crusher recipe: one raw gold yields two gold dusts. Further uses depend on loaded recipes.')
        coal_dust=@('煤的粉末材料，供加工配方使用。','当前未提供默认加工配方；可在JEI或数据包中查看实际用途。','Powdered coal material for processing recipes.','No default processing recipe is provided; check JEI or data packs for available uses.')
        carbon_dust=@('碳的粉末材料，可作为合金配方的辅料。','煤或木炭在粉碎机中制成碳粉；合金冶炼机以2铁粉+1碳粉制成2钢锭。','Powdered carbon material for alloy recipe additives.','Crush coal or charcoal for carbon dust. Alloy smelting uses 2 iron dust + 1 carbon dust to make 2 steel ingots.')
        steel_dust=@('铁粉和煤粉混合得到的钢粉。','1铁粉+1煤粉无序合成1钢粉，可作为后续钢材加工的中间材料。','Steel powder made by mixing iron and coal dust.','Shapelessly mix one iron dust and one coal dust into one steel dust for later steel processing.')
        steel_ingot=@('合金冶炼机制作的钢制材料。','2铁粉+1碳粉→2钢锭；基础周期200 tick，40 FE/t，支持处理矩阵并行。','Steel material produced by alloy smelting.','2 iron dust + 1 carbon dust → 2 steel ingots; base cycle 200 ticks at 40 FE/t, with processing matrix support.')
        emergency_battery=@('临时应急燃料电池。','放入热能发电机后，发电量为煤炭的1.5倍，燃烧时间与煤炭相同；土豆、红石和铜锭无序合成2个。','Emergency fuel cell.','In a thermal generator it produces 1.5× coal power for the same burn time. Shapelessly craft two from a potato, redstone and copper ingot.')
        diamond_dust=@('钻石的粉末材料，供加工配方使用。','当前未提供默认加工配方；可在JEI或数据包中查看实际用途。','Powdered diamond material for processing recipes.','No default processing recipe is provided; check JEI or data packs for available uses.')
        netherite_dust=@('下界合金的粉末材料，供加工配方使用。','当前未提供默认加工配方；可在JEI或数据包中查看实际用途。','Powdered netherite material for processing recipes.','No default processing recipe is provided; check JEI or data packs for available uses.')
        quartz_sand=@('石英砂材料，供加工配方使用。','当前未提供默认加工配方；可在JEI或数据包中查看实际用途。','Quartz sand material for processing recipes.','No default processing recipe is provided; check JEI or data packs for available uses.')
    }
    $translations=[ordered]@{'tooltip.alone_mechanical.expand'=@('按住 [%s] 显示功能和信息','Hold [%s] for function and information')}
    $translations['block.alone_mechanical.separation_core']=@('分离核心','Separation Core')
    foreach($entry in $details.GetEnumerator()){
        $translations["tooltip.alone_mechanical.item.$($entry.Key).function"]=@($entry.Value[0],$entry.Value[2])
        $translations["tooltip.alone_mechanical.item.$($entry.Key).info"]=@($entry.Value[1],$entry.Value[3])
    }
    return $translations
}
